import React, { useState } from'react';
import { useSelector, useDispatch } from'react-redux';
import { cartActions } from './cartSlice';
import { Button, Card, Container, ListGroup, ListGroupItem, Spinner } from'reactstrap';

function CartComponent() {
  const dispatch = useDispatch();
  const items = useSelector((state) => state.cart.items);
  const loading = useSelector((state) => state.cart.loading);
  const [quantity, setQuantity] = useState(1);

  const handleIncreaseQuantity = (id) => {
    setQuantity(quantity + 1);
    dispatch(cartActions.addItem({ id, quantity: quantity + 1 }));
  };

  const handleDecreaseQuantity = (id) => {
    if (quantity > 1) {
      setQuantity(quantity - 1);
      dispatch(cartActions.addItem({ id, quantity: quantity - 1 }));
    }
  };

  const handleRemoveItem = (id) => {
    dispatch(cartActions.removeItem(id));
  };

  if (loading) return <Spinner />;

  return (
    <Container>
      <h1>Cart</h1>
      <ListGroup>
        {items.map((item, index) => (
          <ListGroupItem key={index}>
            <Card>
              <Card.Body>
                <Card.Title>{item.name} x{quantity}</Card.Title>
                <Button
                  color="primary"
                  onClick={() => handleIncreaseQuantity(item.id)}
                >
                  +
                </Button>
                <Button
                  color="primary"
                  onClick={() => handleDecreaseQuantity(item.id)}
                >
                  -
                </Button>
                <Button color="danger" onClick={() => handleRemoveItem(item.id)}>
                  Remove
                </Button>
              </Card.Body>
            </Card>
          </ListGroupItem>
        ))}
      </ListGroup>

      <Button color="success" onClick={() => alert('Checkout complete!')}>
        Checkout
      </Button>
    </Container>
  );
}

export default CartComponent;
```

